function checkServiceReturn<S extends ResponseSchema>(
  schema: S,
  raw: unknown,
): ServiceResult<SchemaOutput<S>> | Promise<ServiceResult<SchemaOutput<S>>>

program:
return when(isThenable(raw), () => thenPromise(resolvePromise(raw), v => checkResponse(schema, v)), () => {
  const result = checkResponse(schema, raw);
  return when(isThenable(result), () => {
    // Nothing can await this; settle it quietly so an async validator's own rejection never
    // surfaces as an unhandled rejection either.
    thenPromise(resolvePromise(result), undefined, () => undefined);
    return schemaError([{
      message: 'schema validates asynchronously but the service returned synchronously; make the service async (return a Promise) or use a synchronous schema',
      path: []
    }]);
  }, () => result);
});

const started = machine.send(state, {
  type: 'FETCH'
}) as AsyncState<D>;
return await attemptAsync(async () => {
  const data = await load();
  return machine.send(started, {
    type: 'RESOLVE',
    data,
    request: started.request,
    at: now()
  }) as AsyncState<D>;
}, async error => machine.send(started, {
  type: 'REJECT',
  error,
  request: started.request
}) as AsyncState<D>);

return {
  isLoading: equals(state.status, 'pending'),
  isError: equals(state.status, 'error'),
  isSuccess: equals(state.status, 'success'),
  isRefetching: and(equals(state.status, 'success'), () => state.fetching)
};

const start = times(state.pageIndex, state.pageSize);
return {
  start,
  end: smallestOf([plus(start, state.pageSize), state.total])
};

const {
  start,
  end
} = sliceBounds(state);
return part(rows, start, end);

return match(event.type, {
  NEXT: () => when(not(canNext(state)), () => state, () => at(plus(state.pageIndex, 1), state.total, state.pageSize)),
  PREVIOUS: () => when(not(canPrevious(state)), () => state, () => at(minus(state.pageIndex, 1), state.total, state.pageSize)),
  GO_TO: () => {
    const next = at(event.pageIndex, state.total, state.pageSize);
    return when(equals(next.pageIndex, state.pageIndex), () => state, () => next);
  },
  SET_PAGE_SIZE: () => when(lessThan(event.pageSize, 1), () => state, () => {
    // Keep the first row of the current page on screen.
    const firstRow = times(state.pageIndex, state.pageSize);
    return at(floorOf(dividedBy(firstRow, event.pageSize)), state.total, event.pageSize);
  }),
  SET_TOTAL: () => at(state.pageIndex, event.total, state.pageSize)
}, () => state);

const state = machine.init({
  total: lengthOf(rows),
  pageSize,
  pageIndex
});
return {
  items: pageItems(rows, state),
  pageIndex: state.pageIndex,
  pageCount: pageCount(lengthOf(rows), pageSize),
  canNext: canNext(state),
  canPrevious: canPrevious(state)
};

const m: AtomMachine<CsvState, CsvEvent<T>, void> = {
  id: 'csv-export',
  init() {
    return {
      status: 'empty',
      csv: '',
      rows: 0
    };
  },
  send(state, event) {
    return when(differs(event.type, 'EXPORT'), () => state, () => when(equals(lengthOf(event.rows), 0), () => when(equals(state.status, 'empty'), () => state, () => m.init()), () => ({
      status: 'ready',
      csv: toCsv(event.rows, columns, options),
      rows: lengthOf(event.rows)
    })));
  },
  stateOf(state) {
    return state.status;
  }
};
return m;

return when(differs(event.type, 'EXPORT'), () => state, () => when(equals(lengthOf(event.rows), 0), () => when(equals(state.status, 'empty'), () => state, () => m.init()), () => ({
  status: 'ready',
  csv: toCsv(event.rows, columns, options),
  rows: lengthOf(event.rows)
})));

let s = start;
let e = end;
when(and(differs(s, null), () => isValidDate(s)), () => s = startOfDay(s));
when(and(differs(e, null), () => isValidDate(e)), () => e = endOfDay(e));
return {
  status: statusOf(s, e),
  start: s,
  end: e
};

return when(differs(r.status, 'complete'), () => false, () => {
  const t = timeOfDate(d);
  return and(atLeast(t, timeOfDate(r.start as Date)), () => atMost(t, timeOfDate(r.end as Date)));
});

return match(event.type, {
  SET_START: () => range(event.date, state.end),
  SET_END: () => range(state.start, event.date),
  PRESET: () => when(lessThan(event.days, 1), () => state, () => lastDays(event.days, event.today)),
  CLEAR: () => when(equals(state.status, 'empty'), () => state, () => range(null, null))
}, () => state);

return {
  status: 'idle',
  text: '',
  query: '',
  dueAt: null,
  delay: orElse(get(input, "delay"), () => 300),
  minLength: orElse(get(input, "minLength"), () => 0)
};

return match(event.type, {
  TYPE: () => ({
    ...state,
    status: 'waiting',
    text: event.text,
    dueAt: plus(event.at, state.delay)
  }),
  TICK: () => when(or(or(differs(state.status, 'waiting'), () => equals(state.dueAt, null)), () => lessThan(event.at, state.dueAt)), () => state, () => settle(state)),
  FLUSH: () => when(differs(state.status, 'waiting'), () => state, () => settle(state)),
  CLEAR: () => when(equals(state.status, 'idle'), () => state, () => machine.init({
    delay: state.delay,
    minLength: state.minLength
  }))
}, () => state);

const emptyA = isEmptyValue(a);
const emptyB = isEmptyValue(b);
return when(and(emptyA, () => emptyB), () => 0, () => when(emptyA, () => 1, () => when(emptyB, () => -1, () => when(and(isA(a, Date), () => isA(b, Date)), () => minus(timeOfDate(a), timeOfDate(b)), () => when(and(isNumber(a), () => isNumber(b)), () => minus(a, b), () => localeCompareText(textFrom(a), textFrom(b), undefined, {
  sensitivity: 'base',
  numeric: true
}))))));

return view({
  ...orElse(get(input, "filters"), () => ({}))
}, orElse(get(input, "search"), () => ''), orElse(get(input, "sort"), () => null));

return applyView(rows, machine.init({
  filters: options.filters,
  search: options.search,
  sort: options.sort
}), orElse(options.searchFields, () => []));

return match(event.type, {
  FETCH_FIRST: () => when(differs(state.loading, undefined), () => state, () => ({
    status: 'pending',
    pages: [],
    loading: null,
    error: null
  })),
  FETCH_NEXT: () => when(or(differs(state.loading, undefined), () => not(hasNextPage(state))), () => state, () => ({
    ...state,
    loading: nextCursor(state),
    error: null
  })),
  RESOLVE: () => when(or(equals(state.loading, undefined), () => differs(event.cursor, state.loading)), () => state, () => ({
    status: 'success',
    pages: added(state.pages, {
      items: event.items,
      cursor: event.cursor,
      nextCursor: event.nextCursor
    }),
    loading: undefined,
    error: null
  })),
  REJECT: () => when(or(equals(state.loading, undefined), () => differs(event.cursor, state.loading)), () => state, () => ({
    ...state,
    status: 'error',
    loading: undefined,
    error: event.error
  })),
  RESET: () => machine.init()
}, () => state);

when(equals(lengthOf(input.steps), 0), () => {
  fail(typeErrorFrom('A multi-step flow needs at least one step.'));
});
return {
  status: positionOf(0, lengthOf(input.steps)),
  steps: input.steps,
  index: 0,
  data: input.data,
  visited: 0,
  blocked: null
};

return when(and(equals(state.status, 'done'), () => differs(event.type, 'RESET')), () => state, () => match(event.type, {
  NEXT: () => {
    const data = merged(state.data, orElse(event.data, () => ({})));
    const step = state.steps[state.index];
    return when(not(canLeave(step, data)), () => at(state, state.index, data, step.id), () => at(state, plus(state.index, 1), data, null));
  },
  BACK: () => when(equals(state.index, 0), () => state, () => at(state, minus(state.index, 1), state.data, null)),
  GO_TO: () => {
    // Only a step already reached can be jumped to, so no step's check is skipped.
    const index = positionWhere(state.steps, s => equals(s.id, event.step));
    return when(or(or(lessThan(index, 0), () => greaterThan(index, state.visited)), () => equals(index, state.index)), () => state, () => at(state, index, state.data, null));
  },
  RESET: () => machine.init({
    steps: state.steps,
    data: state.data
  })
}, () => state));

return reduceTo(events, (s, e) => machine.send(s, e), machine.init({
  steps,
  data
})) as FlowState<D>;

return match(event.type, {
  APPLY: () => when(equals(state.status, 'applied'), () => ({
    ...state,
    value: event.update(state.value)
  }), () => ({
    status: 'applied',
    value: event.update(state.value),
    snapshot: state.value,
    error: null
  })),
  COMMIT: () => when(differs(state.status, 'applied'), () => state, () => when(equals(event.value, undefined), () => ({
    status: 'committed',
    value: state.value,
    snapshot: null,
    error: null
  }), () => ({
    status: 'committed',
    value: event.value,
    snapshot: null,
    error: null
  }))),
  ROLLBACK: () => when(differs(state.status, 'applied'), () => state, () => ({
    status: 'rolledBack',
    value: state.snapshot,
    snapshot: null,
    error: event.error
  }))
}, () => state);

const applied = machine.send(state, {
  type: 'APPLY',
  update
}) as OptimisticState<V>;
return await attemptAsync(async () => {
  const saved = await write(applied.value);
  return when(equals(saved, undefined), () => machine.send(applied, {
    type: 'COMMIT'
  }) as OptimisticState<V>, () => machine.send(applied, {
    type: 'COMMIT',
    value: saved
  }) as OptimisticState<V>);
}, async error => machine.send(applied, {
  type: 'ROLLBACK',
  error
}) as OptimisticState<V>);

return {
  pageIndex: state.pageIndex,
  pageSize: state.pageSize,
  offset: times(state.pageIndex, state.pageSize)
};

return when(equals(pageIndex, state.pageIndex), () => state, () => {
  const keeps = equals(state.status, 'success');
  return {
    ...state,
    pageIndex,
    fetching: true,
    placeholder: keeps,
    error: null
  };
});

return {
  status: 'pending',
  pageIndex: orElse(get(input, "pageIndex"), () => 0),
  pageSize: orElse(get(input, "pageSize"), () => 10),
  items: [],
  total: 0,
  fetching: false,
  placeholder: false,
  error: null
};

return match(event.type, {
  FETCH: () => when(state.fetching, () => state, () => ({
    ...state,
    fetching: true,
    error: null
  })),
  RESOLVE: () => when(or(not(state.fetching), () => differs(event.pageIndex, state.pageIndex)), () => state, () => ({
    ...state,
    status: 'success',
    items: event.items,
    total: event.total,
    pageIndex: clampPage(event.pageIndex, event.total, state.pageSize),
    fetching: false,
    placeholder: false,
    error: null
  })),
  REJECT: () => when(or(not(state.fetching), () => differs(event.pageIndex, state.pageIndex)), () => state, () => ({
    ...state,
    status: 'error',
    error: event.error,
    fetching: false,
    placeholder: false
  })),
  NEXT: () => when(not(hasNextPage(state)), () => state, () => moveTo(state, plus(state.pageIndex, 1))),
  PREVIOUS: () => when(not(hasPreviousPage(state)), () => state, () => moveTo(state, minus(state.pageIndex, 1))),
  GO_TO: () => moveTo(state, clampPage(event.pageIndex, state.total, state.pageSize)),
  SET_PAGE_SIZE: () => when(or(lessThan(event.pageSize, 1), () => equals(event.pageSize, state.pageSize)), () => state, () => {
    const pageIndex = floorOf(dividedBy(times(state.pageIndex, state.pageSize), event.pageSize));
    return {
      ...state,
      pageSize: event.pageSize,
      pageIndex,
      fetching: true,
      placeholder: equals(state.status, 'success'),
      error: null
    };
  })
}, () => state);

const out = setOf();
return when(equals(user, null), () => out, () => {
  each(user.roles, role => {
    each(orElse(table[role], () => []), p => {
      addToWeakSet(out, p);
    });
  });
  return out;
});

const list = flattened([required]);
const missing = missingPermissions(user, table, list);
return when(equals(mode, 'any'), () => lessThan(lengthOf(missing), lengthOf(list)), () => equals(lengthOf(missing), 0));

return match(event.type, {
  CHECK: () => {
    const required = flattened([event.require]);
    const missing = missingPermissions(state.user, state.table, required);
    let status: PermissionState['status'] = 'denied';
    when(can(state.user, state.table, required, orElse(event.mode, () => 'all')), () => status = 'allowed');
    return {
      ...state,
      status,
      required,
      missing
    };
  },
  SET_USER: () => ({
    ...state,
    status: 'unchecked',
    user: event.user,
    required: [],
    missing: []
  })
}, () => state);

return match(event.type, {
  START: () => when(and(differs(state.status, 'stopped'), () => differs(state.status, 'finished')), () => state, () => ({
    ...state,
    status: 'fetching',
    failures: 0,
    error: null,
    nextDelay: null,
    attempts: plus(state.attempts, 1)
  })),
  STOP: () => when(equals(state.status, 'stopped'), () => state, () => ({
    ...state,
    status: 'stopped',
    nextDelay: null
  })),
  TICK: () => when(and(differs(state.status, 'waiting'), () => differs(state.status, 'backoff')), () => state, () => ({
    ...state,
    status: 'fetching',
    nextDelay: null,
    attempts: plus(state.attempts, 1)
  })),
  RESOLVE: () => when(differs(state.status, 'fetching'), () => state, () => when(state.isDone(event.data), () => ({
    ...state,
    status: 'finished',
    data: event.data,
    failures: 0,
    error: null,
    nextDelay: null
  }), () => ({
    ...state,
    status: 'waiting',
    data: event.data,
    failures: 0,
    error: null,
    nextDelay: state.interval
  }))),
  REJECT: () => when(differs(state.status, 'fetching'), () => state, () => {
    const failures = plus(state.failures, 1);
    return when(atLeast(failures, state.maxFailures), () => ({
      ...state,
      status: 'stopped',
      error: event.error,
      failures,
      nextDelay: null
    }), () => ({
      ...state,
      status: 'backoff',
      error: event.error,
      failures,
      nextDelay: backoffDelay(state.interval, failures, state.maxBackoff)
    }));
  })
}, () => state);

return match(event.type, {
  SET: () => when(isSameValue(event.value, state.present), () => state, () => {
    const past = part(added(state.past, state.present), negate(state.limit));
    return history(past, event.value, [], state.limit);
  }),
  UNDO: () => when(not(canUndo(state)), () => state, () => {
    const previous = lastOf(state.past);
    return history(part(state.past, 0, -1), previous, prepended(state.future, state.present), state.limit);
  }),
  REDO: () => when(not(canRedo(state)), () => state, () => {
    const [next, ...rest] = state.future;
    return history(added(state.past, state.present), next, rest, state.limit);
  }),
  CLEAR: () => when(equals(state.status, 'clean'), () => state, () => history([], state.present, [], state.limit))
}, () => state);

return reduceTo(events, (s, e) => machine.send(s, e), machine.init({
  value,
  limit
})) as HistoryState<V>;

return {
  safeParse(values: V): ParseResult<O> {
    const r = safeParse(values);
    return when(r.success, () => ({
      success: true,
      data: r.output as O
    }), () => {
      const issues = mapEach(orElse(r.issues, () => []), i => ({
        path: mapEach(orElse(i.path, () => []), p => p.key),
        message: i.message
      }));
      return {
        success: false,
        error: {
          issues
        }
      };
    });
  }
};

const r = safeParse(values);
return when(r.success, () => ({
  success: true,
  data: r.output as O
}), () => {
  const issues = mapEach(orElse(r.issues, () => []), i => ({
    path: mapEach(orElse(i.path, () => []), p => p.key),
    message: i.message
  }));
  return {
    success: false,
    error: {
      issues
    }
  };
});

const out: Record<string, string> = {};
each(entriesOf(errors), ([key, message]) => {
  const top = firstOf(splitBy(key, '.'));
  const was = get(before as Record<string, unknown>, top);
  const now = get(after as Record<string, unknown>, top);
  when(isSameValue(was, now), () => out[key] = message);
});
return out;

return match(event.type, {
  SUBMIT: () => when(equals(state.status, 'submitting'), () => state, () => validate(state, orElse(event.values, () => state.values))),
  RESOLVE: () => when(differs(state.status, 'submitting'), () => state, () => ({
    ...state,
    status: 'submitted',
    result: event.result
  })),
  REJECT: () => when(differs(state.status, 'submitting'), () => state, () => ({
    ...state,
    status: 'failed',
    error: event.error
  })),
  EDIT: () => when(equals(state.status, 'submitting'), () => state, () => ({
    ...state,
    values: event.values,
    errors: clearEdited(state.errors, state.values, event.values)
  })),
  RESET: () => machine.init({
    schema: state.schema,
    values: orElse(event.values, () => state.values)
  })
}, () => state);

const words = keepWhere(splitBy(trimmed(name), /\s+/), Boolean);
const first = orElse(get(firstOf(words), 0), () => '');
const last = when(greaterThan(lengthOf(words), 1), () => firstOf(lastOf(words)), () => '');
return upperCase(`${first}${last}`);

return when(readOnly, () => undefined, () => {
  setOwn(next);
  onCheckedChange?.(next);
});

when(and(differs(next, open), () => not(and(next, () => readOnly))), () => {
  setOpenState(next);
  onOpenChange?.(next);
});

return when(readOnly, () => undefined, () => {
  setOwnOpen(next);
  onOpenChange?.(next);
});

return when(readOnly, () => undefined, () => {
  setOwn(next);
  onValueChange?.(next);
});

when(and(and(onRemove, () => not(disabled)), () => or(equals(e.key, 'Backspace'), () => equals(e.key, 'Delete'))), () => {
  e.preventDefault();
  onRemove();
});
